def merge_<cycle>(intervals):
    merged = []
    for lo, hi in sorted(intervals):
        if lo > hi:
            raise ValueError('reversed interval')
        if merged and lo <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], hi)
        else:
            merged.append([lo, hi])
    return merged
# Each retained interval starts after the previous one ends.
